function siteSettings(site?: SiteContent) { return site?.settings ?? fallbackSettings; }
function recordImage(record?: ContentRecord) { return record?.image || '/fabric-detail.jpg'; }
function recordImages(record?: ContentRecord) {
  const images = record?.images?.filter(Boolean) || [];
  return Array.from(new Set([recordImage(record), ...images]));
}
function collectionRecords(site: SiteContent | undefined, collection: string, fallbacks: ContentRecord[]) {
  const records = (site as Record<string, unknown> | undefined)?.[collection];
  return (Array.isArray(records) && records.length ? records : fallbacks) as ContentRecord[];
}
function toWhatsapp(number: string, message: string) {
  const digits = number.replace(/\D/g, '');
  return `https://wa.me/${digits}?text=${encodeURIComponent(message)}`;
}

function PageMeta() {
  const [location] = useLocation();
  useEffect(() => {
    const segments = location.split('/').filter(Boolean);
    const pageName = segments.length
      ? segments[segments.length - 1].replace(/-/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase())
      : 'Home';
    const title = location === '/'
      ? 'Ahmed Riaz Textile Factory | Baldia, Karachi'
      : `${pageName} | Ahmed Riaz Textile Factory`;
    const description = location === '/'
      ? 'Ahmed Riaz is a textile manufacturing factory in Baldia, Karachi, producing textile materials and products for bulk requirements.'
      : `${pageName} from Ahmed Riaz Textile Factory, a practical textile manufacturing partner in Baldia, Karachi.`;
    document.title = title;
    const updateMeta = (selector: string, content: string, attribute: string) => {
      const element = document.head.querySelector<HTMLMetaElement>(selector);
      if (element) element.setAttribute(attribute, content);
    };
    updateMeta('meta[name="description"]', description, 'content');
    updateMeta('meta[property="og:title"]', title, 'content');
    updateMeta('meta[property="og:description"]', description, 'content');
    updateMeta('meta[name="twitter:title"]', title, 'content');
    updateMeta('meta[name="twitter:description"]', description, 'content');
    const canonical = document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');
    if (canonical) canonical.href = `${window.location.origin}${location}`;
  }, [location]);
  return null;
}

function ScrollToTop() {
  const [location] = useLocation();
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  }, [location]);
  return null;
}

